document.addEventListener("DOMContentLoaded", function () {
  var targets = document.getElementsByClassName("target");
  var actuals = document.getElementsByClassName("actual");

  for (var i = 0; i < targets.length; i++) {
    var idParts = (targets[i].id || "").split("-");
    var barid = idParts.length > 1 ? idParts[1] : null;
    var targetVal = parseFloat(String(targets[i].textContent || "").replace(/[^0-9.-]/g, ""));
    var actualVal = parseFloat(String(actuals[i] ? actuals[i].textContent : "").replace(/[^0-9.-]/g, ""));
    if (!barid || !isFinite(targetVal) || targetVal <= 0 || !isFinite(actualVal)) continue;

    var percentage = (actualVal / targetVal) * 100;
    var progressBar = document.getElementById("progress-bar-" + barid);
    if (!progressBar) continue;

    var width = Math.min(percentage, 100);
    progressBar.style.width = width + "%";
    progressBar.textContent = percentage.toFixed(0) + "%";

    if (percentage >= 95) {
      progressBar.style.backgroundColor = "#28a745";
      progressBar.style.color = "#fff";
    } else if (percentage >= 75) {
      progressBar.style.backgroundColor = "#2490ef";
      progressBar.style.color = "#fff";
    } else if (percentage > 50) {
      progressBar.style.backgroundColor = "#7eb6e8";
      progressBar.style.color = "#1a3a52";
    } else {
      progressBar.style.backgroundColor = "#c5d9ec";
      progressBar.style.color = "#2c3338";
    }
  }
});
